```typescript
export class SubsystemResolver {
  private dirMap: Map<string, string> = new Map();
  private initialized = false;

  async initialize(executeQuery: (cypher: string) => Promise<any[]>): Promise<void> {
    const folders = await executeQuery(
      `MATCH (f:Folder)
       WHERE f.filePath IS NOT NULL AND NOT f.filePath CONTAINS '/'
       RETURN f.filePath AS dir`
    );
    for (const { dir } of folders) {
      const lower = dir.toLowerCase();
      this.dirMap.set(lower, dir);
      // Also map components: "minerva_nvm" → map both "minerva" and "nvm"
      for (const part of lower.split(/[_\-]/)) {
        if (part.length >= 3 && !this.dirMap.has(part)) {
          this.dirMap.set(part, dir);
        }
      }
    }
    this.initialized = true;
  }

  resolve(query: string): string | null {
    const tokens = query.toLowerCase().split(/\W+/);
    for (const token of tokens) {
      const match = this.dirMap.get(token);
      if (match) return match;
    }
    return null;
  }
}
```

