  const nodeModulesDirs = [
    'node_modules',
    `${process.env.HOME}/.npm/_npx`,
  ];
  for (const dir of nodeModulesDirs) {
    for (const pkg of maliciousPackages) {
      const pkgPath = `${dir}/${pkg}`;
      try {
        const meta = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
        if (meta.name === 'axios' && ['1.14.1', '0.30.4'].includes(meta.version)) {
          warnings.push(`[CRITICAL] Compromised package found: axios@${meta.version} in ${dir}`);
        }
        if (meta.name === 'plain-crypto-js') {
          warnings.push(`[CRITICAL] Trojanized package found: plain-crypto-js@${meta.version} in ${dir}`);
